const categorias = ['Trabalho','Financeiro','Newsletters','Compras','Pessoal','Social','SpamProvavel'];
// emails vem do Limpa json (nao do buscar inbox): o classificar recebe do
// Limpa json, entao o indice i casa com o Limpa json, 1:1 em ordem.
const emails = $('Limpa json').all();
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const email = emails[i] ? emails[i].json : {};
  const raw = (item.json.message?.content ?? item.json.text ?? item.json.content ?? '').toString();
  const limpo = raw.trim().split(/\s+/)[0].replace(/[^A-Za-zÀ-ÿ]/g, '');
  const match = categorias.find(c => c.toLowerCase() === limpo.toLowerCase()) || 'Pessoal';
  item.json.categoria = match;
  item.json.labelName = 'AI/' + match;
  item.json.id = email.id;
  item.json.threadId = email.threadId;
}
return items;

const labels = $('Pessoal: listar labels').all().map(i => i.json);
const byName = {};
for (const l of labels) { byName[l.name] = l.id; }
for (const item of $input.all()) {
  item.json.labelId = byName[item.json.labelName] || null;
}
return $input.all().filter(i => i.json.labelId);

