// Pre-filtro de importancia COMUM as duas contas: roda DEPOIS de arquivar
// (tirar da INBOX), recebendo tanto o ramo Pessoal quanto o Trabalho.
// So deixa passar as categorias que valem checagem de importancia, para
// nao gastar uma chamada de LLM por email em tudo. Alem disso, repoe o
// corpo do email (text/subject/from/date) a partir do 'Limpa json' da conta
// correspondente, que o 'normalizar' nao carregou -- o 'Importancia' precisa
// desses campos. Indexa os DOIS Limpa json por id (id do Gmail e unico, nao
// colide entre contas); o try/catch protege quando o ramo Trabalho esta
// desabilitado e 'Limpa json (Trabalho)' nao executou.
const categoriasImportantes = ['Trabalho','Financeiro','Pessoal','Compras'];

let fontes = [];
try { fontes = fontes.concat($('Limpa json').all()); } catch (e) {}

const byId = {};
for (const e of fontes) { if (e.json.id) byId[e.json.id] = e.json; }

const out = [];
for (const item of $input.all()) {
  if (!categoriasImportantes.includes(item.json.categoria)) continue;
  const corpo = (item.json.id && byId[item.json.id]) ? byId[item.json.id] : {};
  out.push({
    json: {
      ...corpo,       // text, subject, from, date, snippet...
      ...item.json,   // id, threadId, categoria, labelName, labelId (prevalece)
    },
  });
}
return out;

