// Casa o resultado de importancia com o email original e extrai o JSON
// de forma robusta, tolerando os varios formatos que o no de LLM pode
// devolver (API Responses -> output/output_text; chat -> message.content;
// ou texto cru) e JSON embrulhado em ```json ... ``` ou com texto em volta.
//
// O no 'Importancia' (API Responses) NAO preserva os campos do email na
// saida -- devolve so o 'output'. Por isso o email original e recuperado
// a partir dos nos de filtro. Como DOIS ramos convergem no 'Importancia'
// (Pessoal e Trabalho), unimos os dois filtros na MESMA ordem em que o
// 'Importancia' os recebe (Pessoal primeiro, depois Trabalho, conforme as
// conexoes com executionOrder v1) e casamos por id -- id do Gmail e unico,
// entao nao ha ambiguidade mesmo com os dois ramos juntos. O try/catch
// protege quando um ramo esta desabilitado e seu filtro nao executou.

let emails = [];
try { emails = emails.concat($('Filtra importantes').all()); } catch (e) {}
try { emails = emails.concat($('Trabalho: Filtra importantes').all()); } catch (e) {}
const byId = {};
for (const e of emails) { if (e.json.id) byId[e.json.id] = e.json; }

function extrairTexto(json) {
  // API Responses (typeVersion 2.3)
  const out = json.output?.[0]?.content?.find(c => c.type === 'output_text')?.text;
  if (out) return out;
  // chat completions
  if (json.message?.content) return json.message.content;
  // variacoes comuns
  if (typeof json.text === 'string') return json.text;
  if (typeof json.content === 'string') return json.content;
  return '';
}

function extrairJson(texto) {
  let t = (texto || '').trim();
  // remove cercas de codigo ```json ... ```
  t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(t); } catch (e) {}
  // fallback: pega o primeiro bloco {...} dentro do texto
  const m = t.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return null;
}

// Casamento por POSICAO sobre a uniao dos filtros: o resultado i do
// 'Importancia' corresponde ao email i da uniao (mesma ordem de entrada).
// (byId fica disponivel como fallback caso uma versao futura do no de
// importancia passe a devolver o id junto da resposta.)
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const texto = extrairTexto(items[i].json);
  const parsed = extrairJson(texto);
  const email = (items[i].json.id && byId[items[i].json.id]) ? byId[items[i].json.id] : (emails[i] ? emails[i].json : {});

  const result = parsed || {
    important: false,
    reason: 'Falha ao interpretar a resposta do classificador de importancia.',
    priority: 'low',
    summary: ''
  };

  out.push({
    json: {
      ...email,
      ...result,
      // normaliza important para booleano de verdade
      important: result.important === true || result.important === 'true',
      priority: result.priority || 'low',
      reason: result.reason || '',
      summary: result.summary || '',
    },
  });
}
return out;

